from pathlib import Path
B=Path(__file__).resolve().parent;Q=list(csv.DictReader((B/'queue.csv').open(encoding='utf8')));R=list(csv.DictReader((B/'RESULTS.csv').open(encoding='utf8')));S=json.loads((B/'SOURCE-SNAPSHOT.json').read_text(encoding='utf8'));N={x['tic']:x for x in json.loads((B/'helper-pixels/final-neighbors.json').read_text(encoding='utf8'))};rows=[]
